\documentclass{article}
\usepackage{fontspec}
\usepackage{polyglossia}
\setmainlanguage{bengali}
\usepackage{graphicx}
\usepackage{hyperref}
\begin{document}
\section{ভাইরাসের গঠন (Structure of Virus)}
\subsection{প্রকৃতিতে বিভিন্ন ধরনের ভাইরাস রয়েছে। একটি আদর্শ ভাইরাসের গঠন বিশ্লেষণ করলে নিম্নলিখিত অংশগুলি দেখা যায়—
\begin{itemize}
    \item \textbf{ক্যাপসিড (Capsid):} ভাইরাসের প্রোটিনযুক্ত আবরণকে ক্যাপসিড বলে। প্রতিটি ক্যাপসিড ক্যাপসোমিয়ার (capsomere) নামক অনেকগুলো গঠনিক এককের সমন্বয়ে গঠিত। প্রতিটি ডিব্রিয়েন সর্বোচ্চ ২০০০ হতে ২১৩০টি ক্যাপসোমিয়ার থাকে। ক্যাপসোমিয়ারগুলোর বিন্যাসের ভিত্তিতে ভাইরাস ক্যাপসিড বিভিন্ন আকৃতি ধারণ করে। ক্ষেত্র বিশেষে ক্যাপসিডে প্রোটিনের সাথে লিপিড ও স্টার্ট থাকে। ক্যাপসিড ভেতরের বস্তুকে (DNA বা RNA) সুরক্ষা করে এবং অ্যান্টিজেন হিসেবে কাজ করে।
    \item \textbf{আবরণ (Envelop):} কোনো কোনো ভাইরাসে ক্যাপসিডের বাইরে লিপিডযুক্ত অতিরিক্ত একটি আবরণ থাকে। এমন ভাইরাসকে লিপোভাইরাস (lipovirus) বলে; যেমন— HIV। আবরণের গঠনগত একককে পেপলোমিয়ার জীববিজ্ঞান ১ম পত্র (বোর্ড)-১২ক
\end{itemize}
\end{document}

